  W("a quarter", "/ə ˈkwɔːtə/", "phrase", "чверть", "A quarter of the cake.", "Чверть торта."),
  W("a dozen", "/ə ˈdʌzn/", "phrase", "дюжина", "A dozen eggs, please.", "Дюжину яєць, будь ласка."),
